INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2840215, 391071, 33361, '<td valign="top">this is a fabulous try at a zen-like image - but it needs a different colored table, angle camera so that try is straight, and the spot on the wall removed...(nice bonsai thought)</td>', 'this is a fabulous try at a zen-like image - but it needs a different colored table, angle camera so that try is straight, and the spot on the wall removed...(nice bonsai thought)', '2006-09-16 09:26:42.000000', NULL, 1),
(2840217, 394503, 22970, '<td valign="top">Nice idea on the composition but the photo is blown out to the point it is very hard to judge. You must have been shooting into the sun. Next time you may want to try shooting with the sun to your left to get more detail and it will help loose the sun glare.</td>', 'Nice idea on the composition but the photo is blown out to the point it is very hard to judge. You must have been shooting into the sun. Next time you may want to try shooting with the sun to your left to get more detail and it will help loose the sun glare.', '2006-09-16 09:27:32.000000', NULL, 1),
