(2840464, 394233, 60141, '<td valign="top">great shot!  love your vision realizing this in post...well done!</td>', 'great shot!  love your vision realizing this in post...well done!', '2006-09-16 12:00:12.000000', NULL, 1),
(2840465, 392613, 60141, '<td valign="top">beautiful colors!</td>', 'beautiful colors!', '2006-09-16 12:01:21.000000', NULL, 1),
