(2842443, 394507, 53278, '<td valign="top">I really like the colors on this one.7</td>', 'I really like the colors on this one.7', '2006-09-17 12:53:41.000000', NULL, 1),
(2842446, 393952, 53278, '<td valign="top">Interesting Processing</td>', 'Interesting Processing', '2006-09-17 12:54:42.000000', NULL, 1),
(2842457, 392125, 53278, '<td valign="top">Very interesting Shot and composition,8.</td>', 'Very interesting Shot and composition,8.', '2006-09-17 12:58:25.000000', NULL, 1),
(2842460, 394009, 53278, '<td valign="top">The Tree seems out of focus, need to work on lighting, and post processing too.</td>', 'The Tree seems out of focus, need to work on lighting, and post processing too.', '2006-09-17 12:59:26.000000', NULL, 1),
(2842462, 392578, 53278, '<td valign="top">Perhaps a bit more contrast adjustment could have made this shot more dramatic</td>', 'Perhaps a bit more contrast adjustment could have made this shot more dramatic', '2006-09-17 13:00:09.000000', NULL, 1),
(2842467, 393818, 53278, '<td valign="top">Great shot, but we can see part of the tree.</td>', 'Great shot, but we can see part of the tree.', '2006-09-17 13:01:20.000000', NULL, 1),
