(2842473, 394184, 53278, '<td valign="top">Nice perspective too bad we don''t see the whole tree.</td>', 'Nice perspective too bad we don''t see the whole tree.', '2006-09-17 13:04:25.000000', NULL, 1),
(2842474, 393790, 53278, '<td valign="top">Nice colors, but where is the tree???</td>', 'Nice colors, but where is the tree???', '2006-09-17 13:05:02.000000', NULL, 1),
